use std::fmt::Write;
use std::mem::discriminant;

use anyhow::{Context, Error as AnyhowError, Result, bail, ensure};
use serde::Deserialize;
use toml::{Value as TomlValue, from_str};

const GENERATED_HEADER: &str =
    "// Generated by aion-prefs. Edit the source TOML files instead.\n\n";

#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
struct PreferenceFile {
    pref: Vec<Preference>,
}

/// A Firefox runtime default with optional locking and platform conditions.
#[derive(Debug, Deserialize)]
#[serde(deny_unknown_fields)]
pub struct Preference {
    pub name: String,
    value: PreferenceValue,
    #[serde(default)]
    locked: bool,
    #[serde(default)]
    sticky: bool,
    #[serde(default)]
    condition: Option<String>,
    #[serde(default)]
    else_value: Option<PreferenceValue>,
}

/// Native libpref types; quoted booleans and numbers remain strings.
#[derive(Debug, Deserialize)]
#[serde(try_from = "TomlValue")]
enum PreferenceValue {
    Boolean(bool),
    Integer(i32),
    String(String),
}

impl TryFrom<TomlValue> for PreferenceValue {
    type Error = AnyhowError;

    fn try_from(value: TomlValue) -> Result<Self> {
        match value {
            TomlValue::Boolean(value) => Ok(Self::Boolean(value)),
            TomlValue::Integer(value) => Ok(Self::Integer(
                i32::try_from(value).context("preference integers must fit in signed 32 bits")?,
            )),
            TomlValue::String(value) if !value.contains('\0') => Ok(Self::String(value)),
            TomlValue::String(_) => bail!("preference strings cannot contain NUL characters"),
            _ => bail!("expected a boolean, string, or signed 32-bit integer"),
        }
    }
}

pub fn parse(source: &str) -> Result<Vec<Preference>> {
    let config: PreferenceFile = from_str(source)?;
    for pref in &config.pref {
        pref.validate()?;
    }
    Ok(config.pref)
}

impl Preference {
    fn validate(&self) -> Result<()> {
        if self.name.is_empty()
            || self
                .name
                .chars()
                .any(|c| c.is_whitespace() || c.is_control())
        {
            bail!(
                "invalid preference name {:?}: use a nonempty name without whitespace or control characters",
                self.name
            );
        }
        if let Some(condition) = &self.condition
            && (condition.trim().is_empty()
                || condition.chars().any(|c| c.is_control() || c == '#'))
        {
            bail!(
                "{}: condition must be a nonempty, single-line preprocessor expression",
                self.name
            );
        }
        if let Some(fallback) = &self.else_value {
            ensure!(
                self.condition.is_some(),
                "{}: else_value requires condition",
                self.name
            );
            ensure!(
                discriminant(&self.value) == discriminant(fallback),
                "{}: value and else_value must have the same type",
                self.name
            );
        }
        Ok(())
    }
}

pub fn render(preferences: &[Preference]) -> String {
    let mut output = String::from(GENERATED_HEADER);
    for pref in preferences {
        if let Some(condition) = &pref.condition {
            writeln!(output, "#if {}", condition.trim()).unwrap();
        }
        render_statement(&mut output, pref, &pref.value);
        if let Some(fallback) = &pref.else_value {
            output.push_str("#else\n");
            render_statement(&mut output, pref, fallback);
        }
        if pref.condition.is_some() {
            output.push_str("#endif\n");
        }
    }
    output
}

fn render_statement(output: &mut String, pref: &Preference, value: &PreferenceValue) {
    let value = match value {
        PreferenceValue::Boolean(value) => value.to_string(),
        PreferenceValue::Integer(value) => value.to_string(),
        PreferenceValue::String(value) => quote(value),
    };
    let locked = if pref.locked { ", locked" } else { "" };
    let sticky = if pref.sticky { ", sticky" } else { "" };
    writeln!(
        output,
        "pref({}, {value}{locked}{sticky});",
        quote(&pref.name)
    )
    .unwrap();
}

fn quote(value: &str) -> String {
    let mut output = String::from("\"");
    for character in value.chars() {
        match character {
            '"' => output.push_str("\\\""),
            '\\' => output.push_str("\\\\"),
            '\n' => output.push_str("\\n"),
            '\r' => output.push_str("\\r"),
            // libpref accepts Unicode escapes, but not JSON's \t, \b, or \f.
            c if c.is_control() || c == '\u{2028}' || c == '\u{2029}' => {
                write!(output, "\\u{:04X}", c as u32).unwrap();
            }
            c => output.push(c),
        }
    }
    output.push('"');
    output
}

